// Optional authentic fixtures generated by running the published images
// against synthetic appdata. No real account, key, or host configuration is used.
func TestPublishedV1UpgradeAndManualRestore(t *testing.T) {
	testPublishedUpgradeAndManualRestore(t, os.Getenv("ANTENNARR_UPGRADE_FIXTURE"), "v1.0.0")
}

func TestPublishedV104UpgradeAndManualRestore(t *testing.T) {
	testPublishedUpgradeAndManualRestore(t, os.Getenv("ANTENNARR_V104_UPGRADE_FIXTURE"), "v1.0.4")
}

func TestPublishedV109UpgradeAndManualRestore(t *testing.T) {
	testPublishedUpgradeAndManualRestore(t, os.Getenv("ANTENNARR_V109_UPGRADE_FIXTURE"), "v1.0.9")
}

func testPublishedUpgradeAndManualRestore(t *testing.T, source, baseline string) {
	t.Helper()
	if source == "" {
		t.Skip("published-image fixture not supplied")
	}
	raw, e := os.ReadFile(filepath.Join(source, "expected.json"))
	if e != nil {
		t.Fatal(e)
	}
	expected := map[string]string{}
	if e = json.Unmarshal(raw, &expected); e != nil {
		t.Fatal(e)
	}
	if expected["baseline"] != baseline || (baseline != "v1.0.0" && expected["lineup_export"] == "") {
		t.Fatal("invalid published fixture for", baseline)
	}
	channelCount, e := strconv.Atoi(expected["channel_count"])
	if e != nil || channelCount < 1 {
		t.Fatal("invalid fixture channel count")
	}
	root := t.TempDir()
	e = filepath.WalkDir(filepath.Join(source, "data"), func(path string, d fs.DirEntry, e error) error {
		if e != nil {
			return e
		}
		rel, e := filepath.Rel(filepath.Join(source, "data"), path)
		if e != nil {
			return e
		}
		target := filepath.Join(root, rel)
		if d.IsDir() {
			return os.MkdirAll(target, 0700)
		}
		b, e := os.ReadFile(path)
		if e != nil {
			return e
		}
		return os.WriteFile(target, b, 0600)
	})
	if e != nil {
		t.Fatal(e)
	}
	c, e := config.Load(root)
	if e != nil {
		t.Fatal(e)
	}
	originalID := c.DeviceID
	if strconv.FormatBool(c.Settings.ReplenishWhilePlaying) != expected["replenish"] {
		t.Fatal("saved replenishment setting changed")
	}
	if baseline == "v1.0.9" {
		interruptPublishedMigration(t, root)
	}
	s, e := catalog.Open(root)
	if e != nil {
		t.Fatal(e)
	}
	defer s.Close()
	if e = s.RefreshMatching(); e != nil {
		t.Fatal(e)
	}
	c.Settings.RosterTarget = 20
	c.Settings.ReplenishWhilePlaying = true
	if e = config.Save(root, c); e != nil {
		t.Fatal(e)
	}
	if e = s.EnableRosters(catalog.RosterPolicy{Target: 20, Preference: "stability", Race: 5}); e != nil {
		t.Fatal(e)
	}
	if e = s.ReconcileRosters(); e != nil {
		t.Fatal(e)
	}
	if e = s.EnsureRosterPass(time.Now().Unix()); e != nil {
		t.Fatal(e)
	}
	if e = s.DiscoveryFailedReason(31, false, "http_error", "catalogue", 503, true); e != nil {
		t.Fatal(e)
	}
	check := func(c config.Config, s *catalog.Store) {
		t.Helper()
		for table, want := range map[string]int{"accounts": 31, "roster": 30, "channels": channelCount + 109} {
			var n int
			if e := s.DB.QueryRow("SELECT count(*) FROM " + table).Scan(&n); e != nil || n != want {
				t.Fatal(table, n, e)
			}
		}
		var kind, phase string
		var status int
		if e := s.DB.QueryRow("SELECT last_failure_kind,last_failure_phase,last_failure_status FROM accounts WHERE id=31").Scan(&kind, &phase, &status); e != nil || kind != "http_error" || phase != "catalogue" || status != 503 {
			t.Fatal(kind, phase, status, e)
		}
		var schema int
		s.DB.QueryRow("PRAGMA user_version").Scan(&schema)
		if schema != catalog.SchemaVersion {
			t.Fatal(schema)
		}
		if c.DeviceID != originalID || c.Settings.RosterTarget != 20 || !c.Settings.ReplenishWhilePlaying {
			t.Fatal("configuration changed")
		}
		if raw := expected["lineup_export"]; raw != "" {
			var want catalog.Lineup
			if e := json.Unmarshal([]byte(raw), &want); e != nil {
				t.Fatal(e)
			}
			got, e := s.ExportLineup()
			if e != nil || !reflect.DeepEqual(got, want) {
				t.Fatalf("saved channel definitions changed: %v", e)
			}
		}
		// Production advertises the manager's configured viewer limit, which can
		// differ from the legacy Config.Tuners field retained in old appdata.
		manager := stream.New(c.Settings.MaxOutgoingStreams, time.Duration(c.GraceSeconds)*time.Second, nil)
		defer manager.Close()
		server := tuner.Server{Config: c, Streams: manager, BaseURL: expected["base"], ChannelList: func() []config.Channel {
			chs, _ := s.ChannelsForProfile("primary")
			out := []config.Channel{}
			for _, ch := range chs {
				if ch.Enabled {
					out = append(out, config.Channel{ID: ch.ID, Number: ch.Number, Name: ch.Name})
				}
			}
			return out
		}}
		for _, path := range []string{"/discover.json", "/lineup.json", "/device.xml"} {
			w := httptest.NewRecorder()
			server.Handler().ServeHTTP(w, httptest.NewRequest("GET", path, nil))
			if w.Code != 200 || w.Body.String() != expected[path] {
				t.Fatalf("Plex identity/lineup changed: %s\nwant: %s\ngot: %s", path, expected[path], w.Body.String())
			}
		}
	}
	check(c, s)
	profilesBefore, err := s.Profiles()
	if err != nil || len(profilesBefore) != 2 || profilesBefore[1].Enabled {
		t.Fatal("upgrade profile defaults", profilesBefore, err)
	}
	var queueBefore string
	s.DB.QueryRow("SELECT group_concat(position,',') FROM (SELECT position FROM queue_positions ORDER BY kind,source_id)").Scan(&queueBefore)
	name, e := recovery.Create(root, expected["base"], s)
	if e != nil {
		t.Fatal(e)
	}
	archive, e := os.ReadFile(filepath.Join(root, "backups", name))
	if e != nil {
		t.Fatal(e)
	}
	restoredRoot := t.TempDir()
	if _, e = recovery.Stage(restoredRoot, bytes.NewReader(archive), int64(len(archive))); e != nil {
		t.Fatal(e)
	}
	if e = recovery.ApplyPending(restoredRoot); e != nil {
		t.Fatal(e)
	}
	after, e := catalog.Open(restoredRoot)
	if e != nil {
		t.Fatal(e)
	}
	defer after.Close()
	saved, e := config.Load(restoredRoot)
	if e != nil {
		t.Fatal(e)
	}
	check(saved, after)
	profilesAfter, err := after.Profiles()
	if err != nil || !reflect.DeepEqual(profilesBefore, profilesAfter) {
		t.Fatal("profile identities changed on restore", err)
	}
	var queueAfter string
	after.DB.QueryRow("SELECT group_concat(position,',') FROM (SELECT position FROM queue_positions ORDER BY kind,source_id)").Scan(&queueAfter)
	if queueAfter != queueBefore {
		t.Fatal("random queue positions changed on restore")
	}
	beforePass, _ := s.CheckPassStatus()
	afterPass, _ := after.CheckPassStatus()
	if beforePass != afterPass {
		t.Fatal("saved pass progress changed")
	}
	oldLogin, e := config.OpenAdminLogin(root)
	if e != nil {
		t.Fatal(e)
	}
	newLogin, e := config.OpenAdminLogin(restoredRoot)
	if e != nil {
		t.Fatal(e)
	}
	if oldLogin.Current() != newLogin.Current() {
		t.Fatal("login changed")
	}
}

// Interrupt the real startup path after schema 9 has replaced the channels table.
// The caller then retries startup and checks the published fixture's Plex output,
// edited lineup, and restored backup.
func interruptPublishedMigration(t *testing.T, root string) {
	t.Helper()
	db, err := sql.Open("sqlite", filepath.Join(root, "database", "antennarr.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	db.SetMaxOpenConns(1) // Keep the comparison tables on this connection.
	snapshots := map[string]string{"schema": "SELECT type,name,tbl_name,sql FROM main.sqlite_schema"}
	for _, table := range []string{"channels", "output_profiles", "output_assignments", "mappings", "roster", "settings", "accounts", "streams"} {
		snapshots[table] = "SELECT * FROM main." + table
	}
	for name, query := range snapshots {
		if _, err := db.Exec("CREATE TEMP TABLE before_" + name + " AS " + query); err != nil {
			t.Fatal(err)
		}
	}
	if _, err := db.Exec(`CREATE TRIGGER fixture_interrupt BEFORE UPDATE OF name ON output_profiles
		WHEN EXISTS (SELECT 1 FROM pragma_table_info('channels') WHERE name='profile_id')
		BEGIN SELECT RAISE(ABORT, 'fixture migration interrupted'); END`); err != nil {
		t.Fatal(err)
	}
	store, err := catalog.Open(root)
	if err == nil {
		store.Close()
		t.Fatal("migration ignored the interruption")
	}
	if !strings.Contains(err.Error(), "fixture migration interrupted") {
		t.Fatalf("migration failed before the interruption: %v", err)
	}
	if _, err := db.Exec("DROP TRIGGER fixture_interrupt"); err != nil {
		t.Fatal(err)
	}
	var version int
	if err := db.QueryRow("PRAGMA user_version").Scan(&version); err != nil || version != 8 {
		t.Fatalf("schema after interruption: %d, %v", version, err)
	}
	for name, query := range snapshots {
		before := "SELECT * FROM before_" + name
		var changed bool
		if err := db.QueryRow("SELECT EXISTS(" + query + " EXCEPT " + before + ") OR EXISTS(" +
			before + " EXCEPT " + query + ")").Scan(&changed); err != nil || changed {
			t.Fatalf("%s after interruption: changed=%t, err=%v", name, changed, err)
		}
	}
	var missingStation bool
	if err := db.QueryRow(`SELECT EXISTS(SELECT 1 FROM channels c WHERE NOT EXISTS
		(SELECT 1 FROM settings WHERE name='channel_station:'||c.id))`).Scan(&missingStation); err != nil || !missingStation {
		t.Fatalf("fixture must exercise a channel without station metadata: %v", err)
	}
}
